#include <iostream>
using namespace std;

class PowerCore {
private:
    int energy;
public:
    PowerCore(int e = 0) : energy(e) {}
    PowerCore operator+(const PowerCore& other) const {
        return PowerCore(this->energy + other.energy);
    }
    int getEnergy() const { return energy; }
};

int main() {
    PowerCore a(150);
    PowerCore b(200);
    PowerCore c = a + b;
    cout << "Fused Energy: " << c.getEnergy() << endl;
