#include <iostream>
#include <string>
using namespace std;

class Device {
protected:
    string id;
public:
    Device(string i) : id(i) {}
};

class Computer : public Device {
protected:
    int ram;
public:
    Computer(string i, int r) : Device(i), ram(r) {}
};

class QuantumServer : public Computer {
private:
    int qubits;
public:
    QuantumServer(string i, int r, int q) : Computer(i, r), qubits(q) {}
    void specs() {
        cout << "Server: " << id << ", RAM: " << ram << "GB, Qubits: " << qubits << endl;
    }
};

int main() {
    QuantumServer qs("QS-9000", 128, 64);
    qs.specs();
    return 0;
}

