#include <iostream>
#include <vector>
#include <string>
using namespace std;

class UniverseModule {
public:
    virtual string restore() = 0;
    virtual ~UniverseModule() {}
};

class MemoryCore : public UniverseModule {
public:
    string restore() override { return "Memory: Stable"; }
};

class LogicCore : public UniverseModule {
public:
    string restore() override { return "Logic: Purified"; }
};

int main() {
    vector<UniverseModule*> system;
    system.push_back(new MemoryCore());
    system.push_back(new LogicCore());
    for(auto mod : system) {
        cout << mod->restore() << endl;
        delete mod;
    }
    cout << "THE CODEVERSE IS RESTORED 100%!" << endl;
    return 0;
}
